/**
 * The fitted Clef ingest gate: features from one gateQuestions() call, scored by a
 * logistic model trained on what the classifier actually stored (T644). The fitted
 * parameters live in gate-model-params.ts, generated by scripts/eval/clef-gate-fit.ts.
 */
import type { ClefAnswer } from "../../llm/clef-client.js";

export const GATE_FEATURES = [
  "importance", "importance_p0", "importance_p1", "extractable", "extractable_p0",
  "kind_trivial", "kind_coding", "kind_ops", "kind_research",
  "decision", "abandoned", "failure", "unfinished", "facts", "outcome", "delegated", "log_chars",
] as const;

export interface GateModel {
  readonly mean: readonly number[];
  readonly std: readonly number[];
  readonly weights: readonly number[];
  readonly bias: number;
  /** Skip the classifier when the probability of stored output is below this. */
  readonly threshold: number;
}

function get<T extends ClefAnswer["type"]>(a: Record<string, ClefAnswer>, name: string, type: T): Extract<ClefAnswer, { type: T }> {
  const v = a[name];
  if (!v || v.type !== type) throw new Error(`gate answer ${name} is missing or not a ${type}`);
  return v as Extract<ClefAnswer, { type: T }>;
}

export function gateFeatures(answers: Record<string, ClefAnswer>, chars: number): number[] {
  const imp = get(answers, "importance", "score");
  const ext = get(answers, "extractable", "score");
  const kind = get(answers, "kind", "choice").probabilities;
  const n = (name: string) => get(answers, name, "noul").noul;
  return [
    imp.score / 3, imp.probabilities["0"] ?? 0, imp.probabilities["1"] ?? 0, ext.score / 3, ext.probabilities["0"] ?? 0,
    kind["trivial"] ?? 0, kind["coding"] ?? 0, kind["ops"] ?? 0, kind["research"] ?? 0,
    n("decision"), n("abandoned"), n("failure"), n("unfinished"), n("facts"), n("outcome"), n("delegated"),
    Math.log10(Math.max(chars, 1)),
  ];
}

export function gateProbability(model: GateModel, x: readonly number[]): number {
  let z = model.bias;
  for (let i = 0; i < x.length; i++) z += model.weights[i]! * ((x[i]! - model.mean[i]!) / model.std[i]!);
  return 1 / (1 + Math.exp(-z));
}
